namespace sv_311641b02a8949f681d76695097a9f00.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single user circuit.
/// Provides change notification so all subscribed components stay in sync.
/// </summary>
public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Func<Task>? OnWarehouseChanged;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;

        _currentWarehouseId = warehouseId;

        if (OnWarehouseChanged is not null)
        {
            await OnWarehouseChanged.Invoke();
        }
    }

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A - Downtown"),
        ("WH-002", "Warehouse B - Airport"),
        ("WH-003", "Warehouse C - Harbor"),
    ];
}

namespace sv_311641b02a8949f681d76695097a9f00.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribed components.
/// Each user circuit gets its own instance, ensuring independent state per manager.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private int _currentAlertCount;

    public int CurrentAlertCount => _currentAlertCount;

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components receive this notification.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += HandleWarehouseChangedAsync;
    }

    /// <summary>
    /// Simulates a database query returning a random low-stock item count for the warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var random = Random.Shared.Next(0, 16);
        return Task.FromResult(random);
    }

    /// <summary>
    /// Call when a component wants polling to be active. Polling starts on first subscriber.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            StartPolling();
        }
    }

    /// <summary>
    /// Call when a component no longer needs polling. Polling stops when last subscriber leaves.
    /// </summary>
    public void Unsubscribe()
    {
        _subscriberCount--;
        if (_subscriberCount <= 0)
        {
            _subscriberCount = 0;
            StopPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
        _cts = null;
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire immediately on start
        await RefreshAlertCountAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                await RefreshAlertCountAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task RefreshAlertCountAsync()
    {
        _currentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);

        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    private async Task HandleWarehouseChangedAsync()
    {
        if (_subscriberCount > 0)
        {
            await RefreshAlertCountAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= HandleWarehouseChangedAsync;
        StopPolling();
    }
}

