@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-select"><strong>Current Warehouse:</strong></label>
    <select id="warehouse-select" class="form-select form-select-sm d-inline-block w-auto ms-2"
            @onchange="OnWarehouseSelected" value="@WarehouseState.CurrentWarehouseId">
        @foreach (var wh in Services.WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
    }

    private async Task OnWarehouseSelected(ChangeEventArgs e)
